#!/bin/sh
set -eu
python3 - "$HYDRA_WORKFLOW_INPUTS_DIR/subject" "$HYDRA_WORKFLOW_VALIDATION_FILE" "$HYDRA_WORKFLOW_OUTPUTS_DIR/check" <<'PY'
import hashlib,json,sys
subject,validation,out=sys.argv[1:]; data=json.load(open(validation))['data']; b=open(subject,'rb').read(); sh=hashlib.sha256(b).hexdigest(); expected=b'A:validated input\nB:validated input\n'; ok=(b==expected); verdict='pass' if ok else 'fail'; raw={'actual':verdict,'measurement':1,'evidence':'independent exact byte comparison'}; rh=hashlib.sha256(json.dumps(raw,sort_keys=True,separators=(',',':')).encode()).hexdigest(); obs=[{'id':'assembly-case','raw':raw,'raw_sha256':rh}]; eh=hashlib.sha256(json.dumps(obs,sort_keys=True,separators=(',',':')).encode()).hexdigest(); rec={'obligation_id':'assembly-check','subject_manifest_sha256':sh,'validator_identity':'pattern-check-v1','validator_recipe_sha256':data['check-recipe'],'invocation':{'argv':['sh','check.sh'],'exit_code':0 if ok else 1},'environment':{'host':'local','toolchain':'python3/sh'},'case_inventory':['assembly-case'],'observations':obs,'raw_evidence_sha256':eh,'counts':{'executed':1,'failed':0 if ok else 1,'skipped':0},'limitations':['bounded fixture']}; report={'schema_version':3,'execution_status':'completed','evidence_status':'valid' if ok else 'invalid','domain_verdict':verdict,'verdict':verdict,'subject_sha256':sh,'validator_sha256':data['check'],'requirements':['assembly'],'evidence':'independent exact byte comparison','limitations':['bounded fixture'],'evidence_records':[rec]}; json.dump(report,open(out,'w'),separators=(',',':')); open(out,'a').write('\n'); sys.exit(0 if ok else 1)
PY
